content:
:root {
  --color-primary: #1e3a8a;
  --color-primary-light: #3b82f6;
  --color-primary-dark: #172554;
  --color-primary-bg: #eff6ff;
  --color-accent: #0d9488;
  --color-accent-light: #14b8a6;
  --color-accent-bg: #f0fdfa;
  --color-warning: #f59e0b;
  --color-danger: #ef4444;

  --color-bg-app: #f8fafc;
  --color-bg-card: #ffffff;
  --color-border: #e2e8f0;
  --color-border-hover: #cbd5e1;

  --color-text-main: #0f172a;
  --color-text-muted: #64748b;
  --color-text-sub: #94a3b8;
  --color-text-inverse: #ffffff;

  --font-family-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
  --font-family-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family-base);
  background-color: var(--color-bg-app);
  color: var(--color-text-main);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* アプリ全体のコンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}

@media (min-width: 768px) {
  .app-container {
    padding: 36px 24px 64px;
  }
}

/* ヘッダー */
.app-header {
  margin-bottom: 24px;
  text-align: center;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--color-primary-dark);
  letter-spacing: -0.02em;
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
}

@media (min-width: 768px) {
  .app-title {
    font-size: 2.25rem;
  }
}

.app-subtitle {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  max-width: 640px;
  margin: 0 auto;
}

/* バッジ */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1;
}

.badge-primary {
  background-color: var(--color-primary-bg);
  color: var(--color-primary);
  border: 1px solid rgba(59, 130, 246, 0.25);
}

/* サマリーバナー */
.summary-banner {
  background: linear-gradient(135deg, #1e3a8a 0%, #1e40af 50%, #0d9488 100%);
  border-radius: var(--radius-lg);
  padding: 24px;
  color: var(--color-text-inverse);
  box-shadow: var(--shadow-lg);
  margin-bottom: 28px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

@media (min-width: 840px) {
  .summary-banner {
    flex-direction: row;
    align-items: stretch;
    padding: 28px 32px;
  }
}

.summary-highlight {
  flex: 1.1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border-bottom: 1px solid rgba(255, 255, 255, 0.18);
  padding-bottom: 20px;
}

@media (min-width: 840px) {
  .summary-highlight {
    border-bottom: none;
    border-right: 1px solid rgba(255, 255, 255, 0.18);
    padding-bottom: 0;
    padding-right: 32px;
  }
}

.summary-highlight-label {
  font-size: 0.9rem;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.85);
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.summary-highlight-value {
  font-size: 2.5rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: #ffffff;
  font-family: var(--font-family-mono);
  font-variant-numeric: tabular-nums;
  line-height: 1.15;
}

@media (min-width: 768px) {
  .summary-highlight-value {
    font-size: 3rem;
  }
}

.summary-highlight-unit {
  font-size: 1.1rem;
  font-weight: 600;
  margin-left: 4px;
}

.summary-stats-grid {
  flex: 1.4;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  align-content: center;
}

@media (max-width: 440px) {
  .summary-stats-grid {
    grid-template-columns: 1fr;
  }
}

.stat-item {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  padding: 12px 16px;
  border-radius: var(--radius-md);
  border: 1px solid rgba(255, 255, 255, 0.12);
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.stat-label {
  font-size: 0.8rem;
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 4px;
}

.stat-value {
  font-size: 1.35rem;
  font-weight: 700;
  color: #ffffff;
  font-family: var(--font-family-mono);
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
}

.stat-unit {
  font-size: 0.85rem;
  font-weight: 500;
  margin-left: 2px;
  color: rgba(255, 255, 255, 0.9);
}

/* メイン2カラムグリッドレイアウト */
.simulator-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
  margin-bottom: 24px;
}

@media (min-width: 992px) {
  .simulator-grid {
    grid-template-columns: 410px 1fr;
    align-items: start;
  }
}

/* カードコンポーネント */
.card {
  background-color: var(--color-bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
  padding: 24px;
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}

.card:hover {
  box-shadow: var(--shadow-md);
}

.card-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 12px;
}

/* フォーム関連 */
.form-group {
  margin-bottom: 22px;
}

.form-group:last-child {
  margin-bottom: 0;
}

.form-label-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 8px;
}

.form-label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--color-text-main);
}

.form-current-val {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--color-primary);
  font-family: var(--font-family-mono);
}

/* スライダーインプット */
.slider-input {
  width: 100%;
  height: 6px;
  -webkit-appearance: none;
  appearance: none;
  background: #e2e8f0;
  border-radius: var(--radius-full);
  outline: none;
  cursor: pointer;
  margin: 10px 0;
  transition: background 0.15s ease;
}

.slider-input:focus {
  background: #cbd5e1;
}

.slider-input:focus-visible {
  outline: 2px solid var(--color-primary-light);
  outline-offset: 2px;
}

.slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--color-primary);
  box-shadow: 0 2px 4px rgba(30, 58, 138, 0.3);
  cursor: pointer;
  transition: transform 0.1s ease, background-color 0.15s ease;
  border: 2px solid #ffffff;
}

.slider-input::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--color-primary);
  box-shadow: 0 2px 4px rgba(30, 58, 138, 0.3);
  cursor: pointer;
  border: 2px solid #ffffff;
}

.slider-input::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: var(--color-primary-light);
}

.slider-input::-moz-range-thumb:hover {
  transform: scale(1.15);
  background: var(--color-primary-light);
}

/* 数値入力フィールド */
.number-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  margin-top: 6px;
}

.number-input {
  width: 100%;
  padding: 9px 40px 9px 12px;
  font-size: 0.95rem;
  font-family: var(--font-family-mono);
  color: var(--color-text-main);
  background-color: #f8fafc;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  outline: none;
  transition: border-color 0.15s ease, background-color 0.15s ease, box-shadow 0.15s ease;
}

.number-input:focus {
  background-color: #ffffff;
  border-color: var(--color-primary-light);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
}

.input-unit {
  position: absolute;
  right: 12px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-muted);
  pointer-events: none;
}

/* ラジオボタングループ（返済方式など） */
.radio-group {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 8px;
}

.radio-label {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px 14px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-muted);
  background-color: #f8fafc;
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
  text-align: center;
}

.radio-label:hover {
  border-color: var(--color-border-hover);
  background-color: #ffffff;
}

.radio-label:has(.radio-input:checked) {
  border-color: var(--color-primary);
  background-color: var(--color-primary-bg);
  color: var(--color-primary);
  box-shadow: 0 0 0 1px var(--color-primary);
}

.radio-input {
  appearance: none;
  -webkit-appearance: none;
  margin: 0;
  width: 0;
  height: 0;
  opacity: 0;
  position: absolute;
}

/* チャートセクション */
.chart-wrapper {
  width: 100%;
  height: 350px;
  margin-top: 16px;
}

@media (min-width: 768px) {
  .chart-wrapper {
    height: 400px;
  }
}

.chart-tabs {
  display: flex;
  gap: 8px;
  background-color: #f1f5f9;
  padding: 4px;
  border-radius: var(--radius-md);
  width: fit-content;
}

.tab-btn {
  padding: 6px 14px;
  font-size: 0.85rem;
  font-weight: 600;
  border: none;
  background: transparent;
  color: var(--color-text-muted);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.15s ease;
}

.tab-btn:hover {
  color: var(--color-text-main);
}

.tab-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px #ffffff, 0 0 0 4px var(--color-primary-light);
}

.tab-btn-active {
  background-color: #ffffff;
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

/* 償還スケジュールテーブル */
.table-wrapper {
  width: 100%;
  max-height: 440px;
  overflow: hidden;
  overflow-y: auto;
  overflow-x: auto;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  margin-top: 16px;
  background-color: #ffffff;
  -webkit-overflow-scrolling: touch;
}

.schedule-table {
  width: 100%;
  min-width: 580px;
  border-collapse: collapse;
  font-size: 0.875rem;
}

.schedule-table thead {
  position: sticky;
  top: 0;
  background-color: #f8fafc;
  z-index: 10;
}

.th {
  padding: 12px 14px;
  font-weight: 700;
  color: var(--color-text-muted);
  border-bottom: 2px solid var(--color-border);
  white-space: nowrap;
}

.td {
  padding: 10px 14px;
  border-bottom: 1px solid var(--color-border);
  color: var(--color-text-main);
  font-family: var(--font-family-mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.schedule-table tbody tr:hover {
  background-color: #f1f5f9;
}

.schedule-table tbody tr:last-child .td {
  border-bottom: none;
}

.text-right {
  text-align: right;
}

.text-center {
  text-align: center;
}

/* recharts カスタムスタイル微調整 */
.recharts-default-tooltip {
  border-radius: var(--radius-md) !important;
  border: 1px solid var(--color-border) !important;
  box-shadow: var(--shadow-md) !important;
  font-family: var(--font-family-base) !important;
  font-size: 0.85rem !important;
  background-color: rgba(255, 255, 255, 0.95) !important;
  backdrop-filter: blur(4px);
}

export type RepaymentType = 'equal-principal-and-interest' | 'equal-principal';

export interface LoanInput {
  loanAmount: number; // 単位: 円
  interestRate: number; // 単位: % (例: 0.65)
  loanTermYears: number; // 単位: 年 (例: 35)
  repaymentType: RepaymentType;
  bonusPaymentRatio: number; // 単位: % (0〜40)
}

export interface YearlySchedule {
  year: number;
  annualPayment: number;
  principalPayment: number;
  interestPayment: number;
  remainingBalance: number;
  cumulativeInterest: number;
  cumulativePrincipal: number;
}

export interface LoanResult {
  monthlyPayment: number;
  bonusPaymentAmount: number; // ボーナス月加算額（年2回・1回あたり）
  firstMonthPayment?: number;
  lastMonthPayment?: number;
  totalPayment: number;
  totalInterest: number;
  yearlySchedule: YearlySchedule[];
}

export interface LoanFormProps {
  values: LoanInput;
  onChange?: (values: LoanInput) => void;
}

export interface LoanChartsProps {
  yearlySchedule: YearlySchedule[];
}

export interface AmortizationTableProps {
  yearlySchedule: YearlySchedule[];
}

import { LoanInput, LoanResult, YearlySchedule } from '../types';

/**
 * 住宅ローン返済シミュレーション計算
 * - 元利均等返済 (equal-principal-and-interest)
 * - 元金均等返済 (equal-principal)
 * ボーナス併用（年2回加算）にも対応
 */
export const calculateLoan = (input: LoanInput): LoanResult => {
  const {
    loanAmount,
    interestRate,
    loanTermYears,
    repaymentType,
    bonusPaymentRatio
  } = input;

  if (loanAmount <= 0 || loanTermYears <= 0) {
    return {
      monthlyPayment: 0,
      bonusPaymentAmount: 0,
      firstMonthPayment: 0,
      lastMonthPayment: 0,
      totalPayment: 0,
      totalInterest: 0,
      yearlySchedule: []
    };
  }

  const totalMonths = loanTermYears * 12;
  const totalBonusPayments = loanTermYears * 2;
  const monthlyRate = interestRate > 0 ? (interestRate / 100) / 12 : 0;
  const semiAnnualRate = interestRate > 0 ? (interestRate / 100) / 2 : 0;

  // ボーナス返済割合の正規化 (0〜40% を 0〜0.4 に変換)
  const bonusRatio = Math.min(Math.max(bonusPaymentRatio, 0), 40) / 100;
  const bonusPrincipal = Math.round(loanAmount * bonusRatio);
  const monthlyPrincipal = loanAmount - bonusPrincipal;

  // 1. 月々返済額とボーナス返済額の計算
  let baseMonthlyPayment = 0;
  let baseBonusPayment = 0;
  let firstMonthPayment = 0;
  let lastMonthPayment = 0;

  if (repaymentType === 'equal-principal-and-interest') {
    // 元利均等返済
    if (monthlyRate === 0) {
      baseMonthlyPayment = totalMonths > 0 ? monthlyPrincipal / totalMonths : 0;
    } else {
      const compoundFactorMonthly = Math.pow(1 + monthlyRate, totalMonths);
      baseMonthlyPayment = compoundFactorMonthly > 1
        ? (monthlyPrincipal * monthlyRate * compoundFactorMonthly) / (compoundFactorMonthly - 1)
        : (totalMonths > 0 ? monthlyPrincipal / totalMonths : 0);
    }

    if (bonusPrincipal > 0 && totalBonusPayments > 0) {
      if (semiAnnualRate === 0) {
        baseBonusPayment = bonusPrincipal / totalBonusPayments;
      } else {
        const compoundFactorSemi = Math.pow(1 + semiAnnualRate, totalBonusPayments);
        baseBonusPayment = compoundFactorSemi > 1
          ? (bonusPrincipal * semiAnnualRate * compoundFactorSemi) / (compoundFactorSemi - 1)
          : bonusPrincipal / totalBonusPayments;
      }
    } else {
      baseBonusPayment = 0;
    }

    firstMonthPayment = Math.round(baseMonthlyPayment);
    lastMonthPayment = Math.round(baseMonthlyPayment);
  } else {
    // 元金均等返済
    const monthlyPrincipalPerMonth = totalMonths > 0 ? monthlyPrincipal / totalMonths : 0;
    const bonusPrincipalPerBonus = totalBonusPayments > 0 ? bonusPrincipal / totalBonusPayments : 0;

    const firstMonthInterest = monthlyPrincipal * monthlyRate;
    const lastMonthInterest = monthlyPrincipalPerMonth * monthlyRate;

    firstMonthPayment = Math.round(monthlyPrincipalPerMonth + firstMonthInterest);
    lastMonthPayment = Math.round(monthlyPrincipalPerMonth + lastMonthInterest);
    baseMonthlyPayment = firstMonthPayment; // 代表値として初回を表示

    // 初回ボーナス加算額（元金充当額 ＋ 初回6ヶ月分利息）
    if (bonusPrincipal > 0 && totalBonusPayments > 0) {
      const firstBonusInterest = bonusPrincipal * semiAnnualRate;
      baseBonusPayment = bonusPrincipalPerBonus + firstBonusInterest;
    } else {
      baseBonusPayment = 0;
    }
  }

  // 2. 月次シミュレーションの実行（年次スケジュール構築）
  let remMonthlyPrincipal = monthlyPrincipal;
  let remBonusPrincipal = bonusPrincipal;

  let cumulativePrincipal = 0;
  let cumulativeInterest = 0;

  const yearlySchedule: YearlySchedule[] = [];

  let currentYearPrincipal = 0;
  let currentYearInterest = 0;

  for (let m = 1; m <= totalMonths; m++) {
    const isBonusMonth = m % 6 === 0;

    // 月々の元金・利息計算
    let mInterest = 0;
    let mPrincipal = 0;

    if (repaymentType === 'equal-principal-and-interest') {
      if (monthlyRate === 0) {
        mPrincipal = Math.min(remMonthlyPrincipal, monthlyPrincipal / totalMonths);
        mInterest = 0;
      } else {
        mInterest = remMonthlyPrincipal * monthlyRate;
        mPrincipal = Math.min(remMonthlyPrincipal, baseMonthlyPayment - mInterest);
      }
    } else {
      // 元金均等
      mPrincipal = Math.min(remMonthlyPrincipal, monthlyPrincipal / totalMonths);
      mInterest = remMonthlyPrincipal * monthlyRate;
    }

    if (m === totalMonths) {
      // 最終月の端数調整
      mPrincipal = remMonthlyPrincipal;
    }
    remMonthlyPrincipal = Math.max(0, remMonthlyPrincipal - mPrincipal);

    // ボーナス分の計算（6ヶ月ごと）
    let bInterest = 0;
    let bPrincipal = 0;

    if (isBonusMonth && bonusPrincipal > 0) {
      if (repaymentType === 'equal-principal-and-interest') {
        if (semiAnnualRate === 0) {
          bPrincipal = Math.min(remBonusPrincipal, bonusPrincipal / totalBonusPayments);
          bInterest = 0;
        } else {
          bInterest = remBonusPrincipal * semiAnnualRate;
          bPrincipal = Math.min(remBonusPrincipal, baseBonusPayment - bInterest);
        }
      } else {
        bPrincipal = Math.min(remBonusPrincipal, bonusPrincipal / totalBonusPayments);
        bInterest = remBonusPrincipal * semiAnnualRate;
      }

      if (m === totalMonths) {
        // 最終回端数調整
        bPrincipal = remBonusPrincipal;
      }
      remBonusPrincipal = Math.max(0, remBonusPrincipal - bPrincipal);
    }

    const monthTotalPrincipal = mPrincipal + bPrincipal;
    const monthTotalInterest = mInterest + bInterest;

    currentYearPrincipal += monthTotalPrincipal;
    currentYearInterest += monthTotalInterest;
    cumulativePrincipal += monthTotalPrincipal;
    cumulativeInterest += monthTotalInterest;

    // 年末または最終月の場合、年間集計を追加
    if (m % 12 === 0 || m === totalMonths) {
      const yearIndex = Math.ceil(m / 12);
      const remainingBalance = Math.max(0, loanAmount - cumulativePrincipal);

      yearlySchedule.push({
        year: yearIndex,
        annualPayment: Math.round(currentYearPrincipal + currentYearInterest),
        principalPayment: Math.round(currentYearPrincipal),
        interestPayment: Math.round(currentYearInterest),
        remainingBalance: Math.round(remainingBalance),
        cumulativeInterest: Math.round(cumulativeInterest),
        cumulativePrincipal: Math.round(cumulativePrincipal)
      });

      currentYearPrincipal = 0;
      currentYearInterest = 0;
    }
  }

  const roundedTotalInterest = Math.round(cumulativeInterest);
  const roundedTotalPayment = Math.round(loanAmount + roundedTotalInterest);

  return {
    monthlyPayment: Math.round(baseMonthlyPayment),
    bonusPaymentAmount: Math.round(baseBonusPayment),
    firstMonthPayment,
    lastMonthPayment,
    totalPayment: roundedTotalPayment,
    totalInterest: roundedTotalInterest,
    yearlySchedule
  };
};

/**
 * 金額を日本の「◯億◯◯◯万円」または「◯◯万円」にフォーマットする補助関数
 * 万単位未満は四捨五入してすっきりと表示します。
 */
export const formatYenToKanji = (amount: number): string => {
  if (amount <= 0) return '0円';

  const totalMan = Math.round(amount / 10000);
  if (totalMan === 0) {
    return `${Math.round(amount).toLocaleString()}円`;
  }

  const oku = Math.floor(totalMan / 10000);
  const man = totalMan % 10000;

  if (oku > 0) {
    if (man === 0) {
      return `${oku}億円`;
    }
    return `${oku}億${man.toLocaleString()}万円`;
  }

  return `${man.toLocaleString()}万円`;
};

import { useState, useEffect, ChangeEvent } from 'react';
import { LoanFormProps, RepaymentType, LoanInput } from '../types';

interface PresetItem {
  label: string;
  amount: number; // 万円
  rate: number;
  term: number;
  type: RepaymentType;
}

const PRESETS: PresetItem[] = [
  { label: '3,000万 / 変動0.5% / 35年', amount: 3000, rate: 0.5, term: 35, type: 'equal-principal-and-interest' },
  { label: '4,000万 / 変動0.65% / 35年', amount: 4000, rate: 0.65, term: 35, type: 'equal-principal-and-interest' },
  { label: '5,000万 / 変動0.65% / 35年', amount: 5000, rate: 0.65, term: 35, type: 'equal-principal-and-interest' },
  { label: '4,000万 / 固定1.8% / 35年', amount: 4000, rate: 1.8, term: 35, type: 'equal-principal-and-interest' }
];

const LoanForm = ({ values, onChange }: LoanFormProps) => {
  const currentAmountInMan = Math.round((values?.loanAmount ?? 0) / 10000);
  const currentRate = values?.interestRate ?? 0.65;
  const currentTerm = values?.loanTermYears ?? 35;
  const currentBonusRatio = values?.bonusPaymentRatio ?? 0;

  // 入力途中の空文字や不正入力を許容するためのローカル入力文字列状態
  const [amountStr, setAmountStr] = useState(String(currentAmountInMan));
  const [rateStr, setRateStr] = useState(String(currentRate));
  const [termStr, setTermStr] = useState(String(currentTerm));
  const [bonusStr, setBonusStr] = useState(String(currentBonusRatio));

  useEffect(() => {
    setAmountStr(String(currentAmountInMan));
  }, [currentAmountInMan]);

  useEffect(() => {
    setRateStr(String(currentRate));
  }, [currentRate]);

  useEffect(() => {
    setTermStr(String(currentTerm));
  }, [currentTerm]);

  useEffect(() => {
    setBonusStr(String(currentBonusRatio));
  }, [currentBonusRatio]);

  // スライダー変更ハンドラ
  const handleAmountSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = Number(e.target.value);
    setAmountStr(String(val));
    onChange?.({
      ...values,
      loanAmount: val * 10000
    });
  };

  const handleRateSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setRateStr(String(val));
    onChange?.({
      ...values,
      interestRate: isNaN(val) ? 0 : Math.round(val * 1000) / 1000
    });
  };

  const handleTermSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value, 10);
    setTermStr(String(val));
    onChange?.({
      ...values,
      loanTermYears: isNaN(val) ? 1 : val
    });
  };

  const handleBonusSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseInt(e.target.value, 10);
    setBonusStr(String(val));
    onChange?.({
      ...values,
      bonusPaymentRatio: isNaN(val) ? 0 : val
    });
  };

  // テキスト数値フィールド入力
  const handleAmountTextChange = (e: ChangeEvent<HTMLInputElement>) => {
    const text = e.target.value;
    setAmountStr(text);
    const val = Number(text);
    if (!isNaN(val) && val >= 0) {
      onChange?.({
        ...values,
        loanAmount: val * 10000
      });
    }
  };

  const handleAmountBlur = () => {
    const val = Number(amountStr);
    const clamped = isNaN(val) || val < 100 ? 100 : Math.min(10000, Math.round(val));
    setAmountStr(String(clamped));
    onChange?.({
      ...values,
      loanAmount: clamped * 10000
    });
  };

  const handleRateTextChange = (e: ChangeEvent<HTMLInputElement>) => {
    const text = e.target.value;
    setRateStr(text);
    const val = parseFloat(text);
    if (!isNaN(val) && val >= 0) {
      onChange?.({
        ...values,
        interestRate: Math.round(val * 1000) / 1000
      });
    }
  };

  const handleRateBlur = () => {
    const val = parseFloat(rateStr);
    const clamped = isNaN(val) || val < 0.01 ? 0.01 : Math.min(15.0, Math.round(val * 100) / 100);
    setRateStr(String(clamped));
    onChange?.({
      ...values,
      interestRate: clamped
    });
  };

  const handleTermTextChange = (e: ChangeEvent<HTMLInputElement>) => {
    const text = e.target.value;
    setTermStr(text);
    const val = parseInt(text, 10);
    if (!isNaN(val) && val >= 1) {
      onChange?.({
        ...values,
        loanTermYears: val
      });
    }
  };

  const handleTermBlur = () => {
    const val = parseInt(termStr, 10);
    const clamped = isNaN(val) || val < 1 ? 1 : Math.min(50, val);
    setTermStr(String(clamped));
    onChange?.({
      ...values,
      loanTermYears: clamped
    });
  };

  const handleBonusTextChange = (e: ChangeEvent<HTMLInputElement>) => {
    const text = e.target.value;
    setBonusStr(text);
    const val = parseInt(text, 10);
    if (!isNaN(val) && val >= 0) {
      onChange?.({
        ...values,
        bonusPaymentRatio: Math.min(40, val)
      });
    }
  };

  const handleBonusBlur = () => {
    const val = parseInt(bonusStr, 10);
    const clamped = isNaN(val) || val < 0 ? 0 : Math.min(40, val);
    setBonusStr(String(clamped));
    onChange?.({
      ...values,
      bonusPaymentRatio: clamped
    });
  };

  const handleRepaymentTypeChange = (type: RepaymentType) => {
    onChange?.({
      ...values,
      repaymentType: type
    });
  };

  const applyPreset = (preset: PresetItem) => {
    const updated: LoanInput = {
      ...values,
      loanAmount: preset.amount * 10000,
      interestRate: preset.rate,
      loanTermYears: preset.term,
      repaymentType: preset.type
    };
    onChange?.(updated);
  };

  // ボーナス返済対象額の概算（万円）
  const bonusAmountInMan = Math.round((currentAmountInMan * currentBonusRatio) / 100);

  return (
    <div className="card">
      <div className="card-title">
        <span>借入・返済条件の設定</span>
        <span className="badge badge-primary">条件変更</span>
      </div>

      {/* クイックプリセット */}
      <div style={{ marginBottom: '18px' }}>
        <div style={{ fontSize: '0.8rem', fontWeight: 600, color: 'var(--color-text-muted)', marginBottom: '8px' }}>
          よく使われるプリセット
        </div>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
          {PRESETS.map((preset, idx) => (
            <button
              key={idx}
              type="button"
              onClick={() => applyPreset(preset)}
              style={{
                fontSize: '0.75rem',
                padding: '5px 10px',
                borderRadius: 'var(--radius-sm)',
                border: '1px solid var(--color-border)',
                backgroundColor: '#ffffff',
                color: 'var(--color-text-main)',
                cursor: 'pointer',
                transition: 'all 0.15s ease'
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.borderColor = 'var(--color-primary-light)';
                e.currentTarget.style.backgroundColor = 'var(--color-primary-bg)';
                e.currentTarget.style.color = 'var(--color-primary)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.borderColor = 'var(--color-border)';
                e.currentTarget.style.backgroundColor = '#ffffff';
                e.currentTarget.style.color = 'var(--color-text-main)';
              }}
            >
              {preset.label}
            </button>
          ))}
        </div>
      </div>

      {/* 借入希望額 */}
      <div className="form-group">
        <div className="form-label-row">
          <label className="form-label" htmlFor="loan-amount-slider">借入希望額</label>
          <span className="form-current-val">{currentAmountInMan.toLocaleString()} 万円</span>
        </div>
        <input
          id="loan-amount-slider"
          type="range"
          min={100}
          max={10000}
          step={50}
          value={currentAmountInMan}
          onChange={handleAmountSliderChange}
          className="slider-input"
        />
        <div className="number-input-wrapper">
          <input
            id="loan-amount-number"
            type="number"
            min={100}
            max={10000}
            step={10}
            value={amountStr}
            onChange={handleAmountTextChange}
            onBlur={handleAmountBlur}
            className="number-input"
          />
          <span className="input-unit">万円</span>
        </div>
      </div>

      {/* 借入金利 */}
      <div className="form-group">
        <div className="form-label-row">
          <label className="form-label" htmlFor="interest-rate-slider">借入金利 (年利)</label>
          <span className="form-current-val">{currentRate.toFixed(2)} %</span>
        </div>
        <input
          id="interest-rate-slider"
          type="range"
          min={0.1}
          max={10.0}
          step={0.01}
          value={currentRate}
          onChange={handleRateSliderChange}
          className="slider-input"
        />
        <div className="number-input-wrapper">
          <input
            id="interest-rate-number"
            type="number"
            min={0.1}
            max={10.0}
            step={0.01}
            value={rateStr}
            onChange={handleRateTextChange}
            onBlur={handleRateBlur}
            className="number-input"
          />
          <span className="input-unit">%</span>
        </div>
      </div>

      {/* 返済期間 */}
      <div className="form-group">
        <div className="form-label-row">
          <label className="form-label" htmlFor="loan-term-slider">返済期間</label>
          <span className="form-current-val">{currentTerm} 年 ({currentTerm * 12}ヶ月)</span>
        </div>
        <input
          id="loan-term-slider"
          type="range"
          min={1}
          max={40}
          step={1}
          value={currentTerm}
          onChange={handleTermSliderChange}
          className="slider-input"
        />
        <div className="number-input-wrapper">
          <input
            id="loan-term-number"
            type="number"
            min={1}
            max={40}
            step={1}
            value={termStr}
            onChange={handleTermTextChange}
            onBlur={handleTermBlur}
            className="number-input"
          />
          <span className="input-unit">年</span>
        </div>
      </div>

      {/* 返済方式 */}
      <div className="form-group">
        <div className="form-label-row">
          <label className="form-label">返済方式</label>
        </div>
        <div className="radio-group">
          <label className="radio-label">
            <input
              type="radio"
              name="repaymentType"
              value="equal-principal-and-interest"
              checked={values?.repaymentType === 'equal-principal-and-interest'}
              onChange={() => handleRepaymentTypeChange('equal-principal-and-interest')}
              className="radio-input"
            />
            <span>元利均等返済</span>
          </label>
          <label className="radio-label">
            <input
              type="radio"
              name="repaymentType"
              value="equal-principal"
              checked={values?.repaymentType === 'equal-principal'}
              onChange={() => handleRepaymentTypeChange('equal-principal')}
              className="radio-input"
            />
            <span>元金均等返済</span>
          </label>
        </div>
      </div>

      {/* ボーナス返済割合 */}
      <div className="form-group">
        <div className="form-label-row">
          <label className="form-label" htmlFor="bonus-ratio-slider">ボーナス返済比率</label>
          <div style={{ textAlign: 'right' }}>
            <span className="form-current-val">{currentBonusRatio} %</span>
            <span style={{ fontSize: '0.8rem', color: 'var(--color-text-muted)', marginLeft: '6px' }}>
              ({bonusAmountInMan.toLocaleString()}万円分)
            </span>
          </div>
        </div>
        <input
          id="bonus-ratio-slider"
          type="range"
          min={0}
          max={40}
          step={5}
          value={currentBonusRatio}
          onChange={handleBonusSliderChange}
          className="slider-input"
        />
        <div className="number-input-wrapper">
          <input
            id="bonus-ratio-number"
            type="number"
            min={0}
            max={40}
            step={5}
            value={bonusStr}
            onChange={handleBonusTextChange}
            onBlur={handleBonusBlur}
            className="number-input"
          />
          <span className="input-unit">%</span>
        </div>
      </div>
    </div>
  );
};

export default LoanForm;

