import { useState, useMemo } from 'react';
import { AmortizationTableProps, YearlySchedule } from '../types';

type IntervalFilter = 'all' | '5years';

const AmortizationTable = ({ yearlySchedule = [] }: AmortizationTableProps) => {
  const [interval, setInterval] = useState<IntervalFilter>('all');

  const totalYears = yearlySchedule.length;

  // 借入元金の推定（最終年または初年度の合計累計）
  const initialPrincipal = useMemo(() => {
    if (yearlySchedule.length === 0) return 0;
    const lastItem = yearlySchedule[yearlySchedule.length - 1];
    return lastItem.cumulativePrincipal + lastItem.remainingBalance;
  }, [yearlySchedule]);

  const displayedSchedule = useMemo(() => {
    if (interval === 'all') {
      return yearlySchedule;
    }
    // 5年刻み＋最終年
    return yearlySchedule.filter(
      (item) => item.year % 5 === 0 || item.year === totalYears
    );
  }, [yearlySchedule, interval, totalYears]);

  if (yearlySchedule.length === 0) {
    return (
      <div className="card">
        <div className="card-title">
          <span>年次別 返済・残高スケジュール</span>
        </div>
        <div style={{ padding: '36px 16px', textAlign: 'center', color: 'var(--color-text-muted)' }}>
          返済スケジュールデータがありません。条件を入力してください。
        </div>
      </div>
    );
  }

  return (
    <div className="card">
      <div className="card-title">
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span>年次別 返済・残高スケジュール</span>
          <span className="badge badge-primary">全{totalYears}年分</span>
        </div>
        <div className="chart-tabs" role="tablist" aria-label="表示間隔">
          <button
            type="button"
            role="tab"
            aria-selected={interval === 'all'}
            className={interval === 'all' ? 'tab-btn tab-btn-active' : 'tab-btn'}
            onClick={() => setInterval('all')}
          >
            毎年表示
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={interval === '5years'}
            className={interval === '5years' ? 'tab-btn tab-btn-active' : 'tab-btn'}
            onClick={() => setInterval('5years')}
          >
            5年ごと
          </button>
        </div>
      </div>

      <div className="table-wrapper">
        <table className="schedule-table">
          <thead>
            <tr>
              <th className="th text-center">経過年</th>
              <th className="th text-center">返済進捗</th>
              <th className="th text-right">年間返済額</th>
              <th className="th text-right">元金返済分</th>
              <th className="th text-right">利息支払分</th>
              <th className="th text-right">年末ローン残高</th>
              <th className="th text-right">累計返済利息</th>
            </tr>
          </thead>
          <tbody>
            {displayedSchedule.map((item: YearlySchedule) => {
              const progressPct = initialPrincipal > 0
                ? Math.min(100, Math.round((item.cumulativePrincipal / initialPrincipal) * 100))
                : 0;

              return (
                <tr key={item.year}>
                  <td className="td text-center" style={{ fontWeight: 600 }}>
                    {item.year} 年目
                  </td>
                  <td className="td text-center">
                    <span
                      style={{
                        display: 'inline-block',
                        padding: '2px 8px',
                        borderRadius: 'var(--radius-full)',
                        fontSize: '0.75rem',
                        fontWeight: 600,
                        backgroundColor: progressPct === 100 ? '#dcfce7' : '#f1f5f9',
                        color: progressPct === 100 ? '#15803d' : 'var(--color-text-muted)'
                      }}
                    >
                      {progressPct}%
                    </span>
                  </td>
                  <td className="td text-right">¥{item.annualPayment.toLocaleString()}</td>
                  <td className="td text-right">¥{item.principalPayment.toLocaleString()}</td>
                  <td className="td text-right" style={{ color: 'var(--color-warning)' }}>
                    ¥{item.interestPayment.toLocaleString()}
                  </td>
                  <td className="td text-right" style={{ fontWeight: 600 }}>
                    ¥{item.remainingBalance.toLocaleString()}
                  </td>
                  <td className="td text-right">¥{item.cumulativeInterest.toLocaleString()}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AmortizationTable;

