const initialInput: LoanInput = {
  loanAmount: 35000000, // 3,500万円
  interestRate: 0.65, // 0.65%
  loanTermYears: 35, // 35年
  repaymentType: 'equal-principal-and-interest', // 元利均等返済
  bonusPaymentRatio: 0 // ボーナス返済なし
};

const App = () => {
  const [loanInput, setLoanInput] = useState<LoanInput>(initialInput);

  // 住宅ローン計算結果の算出
  const loanResult = useMemo(() => {
    return calculateLoan(loanInput);
  }, [loanInput]);

  const isPrincipalEqual = loanInput.repaymentType === 'equal-principal';
  const hasBonus = loanInput.bonusPaymentRatio > 0;

  const handleReset = () => {
    setLoanInput(initialInput);
  };

  return (
    <div className="app-container">
      {/* ヘッダー */}
      <header className="app-header">
        <h1 className="app-title">
          <Landmark size={32} />
          <span>住宅ローン 返済シミュレーター</span>
        </h1>
        <p className="app-subtitle">
          借入希望額・金利・返済年数から、毎月の返済額・総支払額・年次別推移を瞬時にシミュレーションします。
        </p>
        <div style={{ marginTop: '12px' }}>
          <button
            type="button"
            onClick={handleReset}
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: '6px',
              padding: '6px 14px',
              fontSize: '0.85rem',
              fontWeight: 600,
              color: 'var(--color-text-muted)',
              backgroundColor: '#ffffff',
              border: '1px solid var(--color-border)',
              borderRadius: 'var(--radius-full)',
              cursor: 'pointer',
              boxShadow: 'var(--shadow-sm)',
              transition: 'all 0.15s ease'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.borderColor = 'var(--color-primary-light)';
              e.currentTarget.style.color = 'var(--color-primary)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.borderColor = 'var(--color-border)';
              e.currentTarget.style.color = 'var(--color-text-muted)';
            }}
          >
            <RotateCcw size={14} />
            <span>条件を初期値にリセット</span>
          </button>
        </div>
      </header>

      {/* サマリーハイライトバナー */}
      <section className="summary-banner">
        <div className="summary-highlight">
          <div className="summary-highlight-label">
            <Calculator size={18} />
            <span>
              {isPrincipalEqual ? '月々の返済額（初回）' : '毎月の返済額'}
            </span>
          </div>
          <div className="summary-highlight-value">
            {loanResult.monthlyPayment.toLocaleString()}
            <span className="summary-highlight-unit">円/月</span>
          </div>
          {hasBonus && (
            <div
              style={{
                fontSize: '0.9rem',
                fontWeight: 600,
                marginTop: '6px',
                color: '#fef08a',
                display: 'flex',
                alignItems: 'center',
                gap: '4px'
              }}
            >
              <span>ボーナス月加算（年2回）:</span>
              <span style={{ fontFamily: 'var(--font-family-mono)' }}>
                +{loanResult.bonusPaymentAmount.toLocaleString()}円 / 回
              </span>
            </div>
          )}
          {isPrincipalEqual && loanResult.lastMonthPayment !== undefined && (
            <div style={{ fontSize: '0.85rem', marginTop: '6px', opacity: 0.85 }}>
              最終回: ¥{loanResult.lastMonthPayment.toLocaleString()}（返済につれ毎月減額）
            </div>
          )}
        </div>

        <div className="summary-stats-grid">
          <div className="stat-item">
            <span className="stat-label">借入総額（元金）</span>
            <div className="stat-value">
              {formatYenToKanji(loanInput.loanAmount)}
            </div>
          </div>

          <div className="stat-item">
            <span className="stat-label">総返済額（元金＋利息）</span>
            <div className="stat-value">
              {loanResult.totalPayment.toLocaleString()}
              <span className="stat-unit">円</span>
            </div>
          </div>

          <div className="stat-item">
            <span className="stat-label">利息総額</span>
            <div className="stat-value" style={{ color: '#fde047' }}>
              {loanResult.totalInterest.toLocaleString()}
              <span className="stat-unit">円</span>
            </div>
          </div>

          <div className="stat-item">
            <span className="stat-label">返済期間・金利</span>
            <div className="stat-value">
              {loanInput.loanTermYears}年
              <span className="stat-unit">({loanInput.interestRate}%)</span>
            </div>
          </div>
        </div>
      </section>

      {/* メイングリッド: フォーム ＆ グラフ */}
      <div className="simulator-grid">
        <LoanForm values={loanInput} onChange={setLoanInput} />
        <LoanCharts yearlySchedule={loanResult.yearlySchedule} />
      </div>

      {/* 償還スケジュールテーブル */}
      <AmortizationTable yearlySchedule={loanResult.yearlySchedule} />
    </div>
  );
};

export default App;
